function fieldValue(string $name):string{return trim((string)($_POST[$name]??''));}
function renderField(string $name,array $field,array $record=[]):void{
 [$label,$type,$limit]=$field;$value=(string)($record[$name]??'');echo '<div class="field"><label for="'.h($name).'">'.h($label).'</label>';
 if($type==='textarea')echo '<textarea id="'.h($name).'" name="'.h($name).'" rows="4" required>'.h($value).'</textarea>';
 elseif($type==='select'||$type==='select_optional'){echo '<select id="'.h($name).'" name="'.h($name).'" '.($type==='select'?'required':'').'><option value="">Select</option>';foreach($limit as $o)echo '<option value="'.h($o).'" '.($value===$o?'selected':'').'>'.h(ucwords(str_replace('_',' ',$o))).'</option>';echo '</select>';}
 elseif($type==='center'){$rows=db()->query("SELECT center_id,center_name FROM evacuation_centers WHERE status='open' ORDER BY center_name")->fetchAll();echo '<select id="center_id" name="center_id" required><option value="">Select open center</option>';foreach($rows as $r)echo '<option value="'.(int)$r['center_id'].'" '.($value==(string)$r['center_id']?'selected':'').'>'.h($r['center_name']).'</option>';echo '</select>';}
 else echo '<input id="'.h($name).'" name="'.h($name).'" type="'.(str_contains($type,'number')?'number':'text').'" maxlength="'.(int)$limit.'" value="'.h($value).'" '.($type==='number'?'min="1" required':'').($type==='number_optional'?'min="0"':'').' '.($type==='text'?'required':'').'>';
 echo '</div>';
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verifyCsrfToken();$action=(string)($_POST['action']??'');
 try{
