   elseif($action==='link_household'){requirePermission('incidents.affected_households');$household=(int)($_POST['household_id']??0);$link=$pdo->prepare('INSERT INTO incident_households(incident_id,household_id,recorded_by) VALUES(:incident,:household,:uid)');try{$link->execute(['incident'=>$id,'household'=>$household,'uid'=>currentStaff()['user_id']]);}catch(PDOException $duplicate){if((int)($duplicate->errorInfo[1]??0)!==1062)throw $duplicate;throw new RuntimeException('That household is already linked to this incident.');}auditLog('link_affected_household','incident',$id,'Household ID '.$household);}
