  }elseif($module==='response'){
   $id=(int)($_POST['id']??0);
   if($action==='assign'){requirePermission('response.assign');$team=trim((string)($_POST['response_team']??''));if($team==='')throw new RuntimeException('Enter the response team name.');$check=$pdo->prepare('SELECT status FROM incidents WHERE incident_id=:id');$check->execute(['id'=>$id]);$currentStatus=$check->fetchColumn();if(!in_array($currentStatus,['verified','responding'],true))throw new RuntimeException('Incident must be verified before assigning a response team.');$s=$pdo->prepare('UPDATE incidents SET response_team=:team,assigned_to=:assigned,status="responding" WHERE incident_id=:id');$s->execute(['team'=>$team,'assigned'=>($_POST['assigned_to']??'')!==''?(int)$_POST['assigned_to']:null,'id'=>$id]);auditLog('assign_response','incident',$id);}
   elseif($action==='update'){requirePermission('response.update');$status=(string)($_POST['status']??'');if(!in_array($status,['responding','resolved'],true))throw new RuntimeException('Invalid response status.');$check=$pdo->prepare('SELECT status FROM incidents WHERE incident_id=:id');$check->execute(['id'=>$id]);$currentStatus=$check->fetchColumn();if(!in_array($currentStatus,['verified','responding'],true))throw new RuntimeException('Only verified or responding incidents can be updated.');$s=$pdo->prepare('UPDATE incidents SET action_taken=:action,status=:status WHERE incident_id=:id');$s->execute(['action'=>trim((string)$_POST['action_taken']),'status'=>$status,'id'=>$id]);auditLog('update_response','incident',$id);}
  }elseif($module==='items'&&$action==='stock'){
   requirePermission('inventory.stock');$item=(int)$_POST['item_id'];$qty=(int)$_POST['quantity'];$type=(string)$_POST['movement_type'];if($qty<1||!in_array($type,['in','out'],true))throw new RuntimeException('Enter a valid stock movement.');
   $pdo->beginTransaction();$lock=$pdo->prepare('SELECT stock_qty FROM relief_items WHERE item_id=:id FOR UPDATE');$lock->execute(['id'=>$item]);$stock=$lock->fetchColumn();if($stock===false)throw new RuntimeException('Item not found.');$new=(int)$stock+($type==='in'?$qty:-$qty);if($new<0)throw new RuntimeException('Insufficient stock for stock-out.');$pdo->prepare('UPDATE relief_items SET stock_qty=:qty WHERE item_id=:id')->execute(['qty'=>$new,'id'=>$item]);$pdo->prepare('INSERT INTO stock_movements(item_id,movement_type,quantity,remarks,recorded_by) VALUES(:item,:type,:qty,:remarks,:uid)')->execute(['item'=>$item,'type'=>$type,'qty'=>$qty,'remarks'=>trim((string)$_POST['remarks']),'uid'=>currentStaff()['user_id']]);$pdo->commit();auditLog('stock_'.$type,'relief_item',$item,'Quantity '.$qty);
  }elseif($module==='distribution'&&$action==='release'){
