   $pdo->beginTransaction();$lock=$pdo->prepare('SELECT stock_qty FROM relief_items WHERE item_id=:id FOR UPDATE');$lock->execute(['id'=>$item]);$stock=$lock->fetchColumn();if($stock===false||(int)$stock<$qty)throw new RuntimeException('The selected item has insufficient stock.');$d=$pdo->prepare('INSERT INTO relief_distributions(household_id,incident_id,item_id,quantity,received_by,distributed_by) VALUES(:household,:incident,:item,:qty,:received,:uid)');$d->execute(['household'=>$household,'incident'=>$incident,'item'=>$item,'qty'=>$qty,'received'=>$received,'uid'=>currentStaff()['user_id']]);$distributionId=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE relief_items SET stock_qty=stock_qty-:qty WHERE item_id=:item')->execute(['qty'=>$qty,'item'=>$item]);$pdo->prepare('INSERT INTO stock_movements(item_id,movement_type,quantity,remarks,recorded_by) VALUES(:item,"out",:qty,:remarks,:uid)')->execute(['item'=>$item,'qty'=>$qty,'remarks'=>'Relief distribution #'.$distributionId,'uid'=>currentStaff()['user_id']]);$pdo->commit();auditLog('release_relief','distribution',$distributionId);
  }elseif($module==='announcements'&&$action==='toggle'){
   requirePermission('announcements.edit');$id=(int)$_POST['id'];$active=(int)($_POST['active']??0);$pdo->prepare('UPDATE announcements SET is_active=:active WHERE announcement_id=:id')->execute(['active'=>$active,'id'=>$id]);auditLog($active?'publish':'unpublish','announcement',$id);
  }elseif($module==='evacuees'&&$action==='checkout'){
