  }elseif($module==='evacuees'&&$action==='create'){
   requirePermission('evacuation.evacuate');$center=(int)$_POST['center_id'];$name=trim((string)$_POST['evacuee_name']);$age=($_POST['age']??'')!==''?(int)$_POST['age']:null;$sex=($_POST['sex']??'')!==''?(string)$_POST['sex']:null;$household=($_POST['household_id']??'')!==''?(int)$_POST['household_id']:null;$incident=($_POST['incident_id']??'')!==''?(int)$_POST['incident_id']:null;if($name===''||strlen($name)>100)throw new RuntimeException('Enter a valid evacuee name.');
   $pdo->beginTransaction();$c=$pdo->prepare('SELECT capacity FROM evacuation_centers WHERE center_id=:id AND status="open" FOR UPDATE');$c->execute(['id'=>$center]);$capacity=$c->fetchColumn();if($capacity===false)throw new RuntimeException('Select an open evacuation center.');$count=$pdo->prepare('SELECT COUNT(*) FROM evacuees WHERE center_id=:id AND time_out IS NULL');$count->execute(['id'=>$center]);$occupants=(int)$count->fetchColumn();if($occupants>=(int)$capacity)throw new RuntimeException('This evacuation center has reached its registered capacity.');$i=$pdo->prepare('INSERT INTO evacuees(center_id,household_id,incident_id,evacuee_name,age,sex) VALUES(:center,:household,:incident,:name,:age,:sex)');$i->execute(['center'=>$center,'household'=>$household,'incident'=>$incident,'name'=>$name,'age'=>$age,'sex'=>$sex]);$newCount=$occupants+1;$pdo->prepare('UPDATE evacuation_centers SET status="full" WHERE center_id=:id AND :occupants>=capacity')->execute(['id'=>$center,'occupants'=>$newCount]);$evacueeId=(int)$pdo->lastInsertId();$pdo->commit();auditLog('evacuee_checkin','evacuee',$evacueeId);
  }elseif(isset($config['fields'])&&in_array($action,['create','update'],true)){
   $isUpdate=$action==='update';requirePermission($module==='evacuees'?'evacuation.evacuate':$config['permission'].($isUpdate?'.edit':'.create'));$values=[];
   foreach($config['fields'] as $name=>$field){$value=fieldValue($name);if(in_array($field[1],['number','number_optional','center'],true))$value=$value===''?null:(int)$value;if($field[1]==='text'&&$value==='')throw new RuntimeException($field[0].' is required.');$values[$name]=$value;}
