   if($isUpdate){$id=(int)$_POST['id'];$sets=[];foreach(array_keys($values) as $f)$sets[]='`'.$f.'`=:'.$f;$values['record_id']=$id;$sql='UPDATE `'.$config['table'].'` SET '.implode(',',$sets).' WHERE `'.$config['id'].'`=:record_id';$pdo->prepare($sql)->execute($values);auditLog('edit',$module,$id);}
   else{$cols=array_keys($values);$sql='INSERT INTO `'.$config['table'].'` (`'.implode('`,`',$cols).'`) VALUES (:'.implode(',:',$cols).')';$pdo->prepare($sql)->execute($values);auditLog('create',$module,(int)$pdo->lastInsertId());}
  }
  $notice='Changes saved successfully.';
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());$error=$e instanceof RuntimeException?$e->getMessage():'The operation could not be completed. Check the database and try again.';}
