dit')):?><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><input type="hidden" name="action" value="edit"><input type="hidden" name="id" value="<?=$r['incident_id']?>"><select name="incident_type"><?php foreach(['flood','fire','landslide','road_obstruction','other'] as $t):?><option value="<?=$t?>" <?=$r['incident_type']===$t?'selected':''?>><?=$t?></option><?php endforeach;?></select><input name="location" value="<?=h($r['location'])?>" required><textarea name="description" rows="2" required><?=h($r['description'])?></textarea><button class="button small">Save</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
