<section class="panel"><h2>Current stock</h2><div class="table-wrap"><table><tr><th>Item</th><th>Category</th><th>Unit</th><th>Available</th></tr><?php foreach($items as $r):?><tr><td><?=h($r['item_name'])?></td><td><?=h($r['category'])?></td><td><?=h($r['unit'])?></td><td><?=$r['stock_qty']?></td></tr><?php endforeach;?></table></div><?php if(hasPermission('inventory.stock')):?><h2>Record stock-in / stock-out</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><input type="hidden" name="action" value="stock"><div class="form-grid"><div class="field"><label>Item</label><select name="item_id" required><?php foreach($items as $r):?><option value="<?=$r['item_id']?>"><?=h($r['item_name'])?> (<?=$r['stock_qty']?> <?=$r['unit']?>)</option><?php endforeach;?></select></div><div class="field"><label>Movement</label><select name="movement_type"><option value="in">Stock-in</option><option value="out">Stock-out</option></select></div><div class="field"><label>Quantity</label><input type="number" min="1" name="quantity" required></div><div class="field"><label>Remarks / source</label><input name="remarks" maxlength="255"></div></div><button class="button">Record movement</button></form><?php endif;?><h2>Stock movement history</h2><?php $movements=$pdo->query('SELECT m.movement_date,i.item_name,m.movement_type,m.quantity,m.remarks,u.full_name FROM stock_movements m JOIN relief_items i ON i.item_id=m.item_id JOIN users u ON u.user_id=m.recorded_by ORDER BY m.movement_date DESC LIMIT 100')->fetchAll();?><div class="table-wrap"><table><tr><th>Date</th><th>Item</th><th>Movement</th><th>Quantity</th><th>Remarks</th><th>Recorded by</th></tr><?php foreach($movements as $m):?><tr><td><?=h($m['movement_date'])?></td><td><?=h($m['item_name'])?></td><td><?=h($m['movement_type'])?></td><td><?=$m['quantity']?></td><td><?=h($m['remarks']??'')?></td><td><?=h($m['full_name'])?></td></tr><?php endforeach;?></table></div></section>
<?php elseif($module==='distribution'):$households=$pdo->query('SELECT household_id,household_head,address FROM households ORDER BY household_head')->fetchAll();$items=$pdo->query('SELECT item_id,item_name,unit,stock_qty FROM relief_items WHERE stock_qty>0 ORDER BY item_name')->fetchAll();$history=$pdo->query('SELECT d.distribution_date,h.household_head,i.item_name,d.quantity,i.unit,d.received_by FROM relief_distributions d JOIN households h ON h.household_id=d.household_id JOIN relief_items i ON i.item_id=d.item_id ORDER BY d.distribution_date DESC')->fetchAll();?>
<section class="panel"><h2>Release relief goods</h2><?php if(hasPermission('distribution.create')):?><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><input type="hidden" name="action" value="release"><div class="form-grid"><div class="field"><label>Affected household</label><select name="household_id" required><?php foreach($households as $hrow):?><option value="<?=$hrow['household_id']?>"><?=h($hrow['household_head'].' — '.$hrow['address'])?></option><?php endforeach;?></select></div><div class="field"><label>Relief item</label><select name="item_id" required><?php foreach($items as $it):?><option value="<?=$it['item_id']?>"><?=h($it['item_name'].' ('.$it['stock_qty'].' '.$it['unit'].' available)')?></option><?php endforeach;?></select></div><div class="field"><label>Quantity</label><input type="number" name="quantity" min="1" required></div><div class="field"><label>Receiving representative</label><input name="received_by" maxlength="100" required></div><div class="field"><label>Incident ID (optional)</label><input type="number" name="incident_id" min="1"></div></div><button class="button">Record distribution</button></form><?php else:?><p>No distribution permission granted.</p><?php endif;?><h2>Distribution history</h2><div class="table-wrap"><table><tr><th>Date</th><th>Household</th><th>Item</th><th>Quantity</th><th>Received by</th></tr><?php foreach($history as $d):?><tr><td><?=h($d['distribution_date'])?></td><td><?=h($d['household_head'])?></td><td><?=h($d['item_name'])?></td><td><?=$d['quantity']?> <?=h($d['unit'])?></td><td><?=h($d['received_by'])?></td></tr><?php endforeach;?></table></div></section>
<?php elseif($module==='evacuees'):$rows=$pdo->query('SELECT e.*,c.center_name FROM evacuees e JOIN evacuation_centers c ON c.center_id=e.center_id ORDER BY e.time_in DESC')->fetchAll();?>
<section class="panel"><h2>Register evacuee</h2><?php if(hasPermission('evacuation.evacuate')):?><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><input type="hidden" name="action" value="create"><div class="form-grid"><?php foreach($config['fields'] as $name=>$field)renderField($name,$field);?></div><button class="button">Register evacuee</button></form><?php endif;?><h2>Evacuation history</h2><div class="table-wrap"><table><tr><th>Name</th><th>Center</th><th>Time in</th><th>Time out</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['evacuee_name'])?></td><td><?=h($r['center_name'])?></td><td><?=h($r['time_in'])?></td><td><?=h($r['time_out']??'Currently staying')?></td><td><?php if(!$r['time_out']&&hasPermission('evacuation.evacuate')):?><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><input type="hidden" name="action" value="checkout"><input type="hidden" name="id" value="<?=$r['evacuee_id']?>"><button class="button small">Check out</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section>
<?php endif;?>
<?php if(isset($config['fields'])&&$module!=='evacuees'):$rows=$module==='centers'?$pdo->query('SELECT c.*,(SELECT COUNT(*) FROM evacuees e WHERE e.center_id=c.center_id AND e.time_out IS NULL) current_occupants FROM evacuation_centers c ORDER BY c.center_name')->fetchAll():$pdo->query('SELECT * FROM `'.$config['table'].'` ORDER BY `'.$config['id'].'` DESC')->fetchAll();?>
<section class="panel"><h2>Saved records</h2><div class="table-wrap"><table><thead><tr><?php foreach(array_keys($config['fields']) as $f):?><th><?=h($config['fields'][$f][0])?></th><?php endforeach;?><?php if($module==='centers'):?><th>Current occupants</th><?php endif;?><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach(array_keys($config['fields']) as $f):?><td><?=h((string)($r[$f]??''))?></td><?php endforeach;?><?php if($module==='centers'):?><td><?= (int)$r['current_occupants'] ?> / <?= (int)$r['capacity'] ?></td><?php endif;?><td><?php if(hasPermission($config['permission'].'.edit')):?><a href="workspace.php?module=<?=h($module)?>&edit=<?=$r[$config['id']]?>">Edit</a><?php endif;?><?php if($module==='announcements'&&hasPermission('announcements.edit')):?><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r[$config['id']]?>"><button class="button small" name="active" value="<?=$r['is_active']?0:1?>"><?=$r['is_active']?'Unpublish':'Publish'?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php endif;?>
<?php if($module==='reports'):$counts=$pdo->query('SELECT status,COUNT(*) total FROM incidents GROUP BY status')->fetchAll();$affected=$pdo->query('SELECT i.incident_id,i.incident_type,COUNT(ih.household_id) affected_households FROM incidents i LEFT JOIN incident_households ih ON ih.incident_id=i.incident_id GROUP BY i.incident_id,i.incident_type ORDER BY i.incident_id DESC')->fetchAll();$occupancy=$pdo->query('SELECT c.center_name,c.capacity,COUNT(e.evacuee_id) occupants FROM evacuation_centers c LEFT JOIN evacuees e ON e.center_id=c.center_id AND e.time_out IS NULL GROUP BY c.center_id')->fetchAll();$stock=$pdo->query('SELECT item_name,unit,stock_qty FROM relief_items ORDER BY item_name')->fetchAll();$dist=$pdo->query('SELECT h.household_head,i.item_name,d.quantity,i.unit,d.received_by,d.distribution_date FROM relief_distributions d JOIN households h ON h.household_id=d.household_id JOIN relief_items i ON i.item_id=d.item_id ORDER BY d.distribution_date DESC')->fetchAll();?>
<section class="panel"><h2>Incident statistics</h2><div class="table-wrap"><table><tr><th>Status</th><th>Total</th></tr><?php foreach($counts as $r):?><tr><td><?=h($r['status'])?></td><td><?=$r['total']?></td></tr><?php endforeach;?></table></div><h2>Affected households by incident</h2><div class="table-wrap"><table><tr><th>Incident</th><th>Type</th><th>Affected households</th></tr><?php foreach($affected as $r):?><tr><td>#<?=$r['incident_id']?></td><td><?=h($r['incident_type'])?></td><td><?=$r['affected_households']?></td></tr><?php endforeach;?></table></div><h2>Evacuation center occupancy</h2><div class="table-wrap"><table><tr><th>Center</th><th>Capacity</th><th>Occupants</th></tr><?php foreach($occupancy as $r):?><tr><td><?=h($r['center_name'])?></td><td><?=$r['capacity']?></td><td><?=$r['occupants']?></td></tr><?php endforeach;?></table></div><h2>Inventory balances</h2><div class="table-wrap"><table><tr><th>Item</th><th>Balance</th></tr><?php foreach($stock as $r):?><tr><td><?=h($r['item_name'])?></td><td><?=$r['stock_qty']?> <?=h($r['unit'])?></td></tr><?php endforeach;?></table></div><h2>Relief distribution report</h2><div class="table-wrap"><table><tr><th>Household</th><th>Item</th><th>Quantity</th><th>Received by</th><th>Date</th></tr><?php foreach($dist as $r):?><tr><td><?=h($r['household_head'])?></td><td><?=h($r['item_name'])?></td><td><?=$r['quantity']?> <?=h($r['unit'])?></td><td><?=h($r['received_by'])?></td><td><?=h($r['distribution_date'])?></td></tr><?php endforeach;?></table></div><p class="muted">To print or save this report as PDF, use your browser's Print command (Ctrl+P).</p></section>
<?php endif;?>
